function BattlingEnemySkillDesc:ReloadNodeInfo(skillInfo, roleId)
    xTry(function()
        local skillId = skillInfo.id
        local skillStar = skillInfo.star
        local skillVo = UIBattlingTools.GetSkillCardInfoByTwoParam(skillId, 1)
        local skillType = skillVo.skillType
        local isPowerful = skillVo.isPowerful
        local isAoe = checkBool(checkNumber(skillVo.isAoe) > 0)
        -- if checkInt(skillType) >= 3 then -- SP技能
        --     self.Img_SkillIcon.Status = 2
        -- else -- 非SP技能
        --     self.Img_SkillIcon.Status = (not IsNull(isPowerful) and checkInt(isPowerful) > 0) and 3 or 1
        -- end
        -- KTool.SetActive(self.Img_SkillTypeIcon.gameObject, skillType < 3)
        if skillType < 3 then
            local label = skillVo.showLabel -- 技能 Icon
            local showLabel = UICommonUtils:GetSkillShowLabelWithStar(label, 1)
            local condition = showLabel >= 1 and showLabel <= 6 and isAoe
            local skillIconPath = condition and UIBattlingTools.GetEnemySkillTypeAOEIconPath_1(showLabel) or
            UIBattlingTools.GetEnemySkillTypeIconPath_1(showLabel)
            UIBattlingCtrlMgr:GetInstance():SetImgByDynamicAtlas(self.Img_SkillTypeIcon, skillIconPath)
        else
            UIBattlingCtrlMgr:GetInstance():SetImgByDynamicAtlas(self.Img_SkillTypeIcon, "UIBattlingDynamicAtlas/battle_icon_sp.png")
        end
        self.skillId = skillId
        self.skillDesc = checkString(table.concat(CardUtils.ParseSkillDescBySkillId(self.skillId, 1)))
        local skillCardVo = UIBattlingTools.GetSkillCardInfoByTwoParam(skillId)
        self.skillName = checkString(skillCardVo.skillName)
    end)
end

function BattlingEnemySkillDesc:SetSkillDescriptionShow()
    ResourceModule.LoadGameObjectAsync("Prefabs/Common/CommonTipsBoardBuff.prefab", function(go)
        if not KTool.IsNull(go) and not KTool.IsNull(self.controller.gameObject) then
            self.tipsBoard = go
            go.name = "CommonTipsBoardBuff"
            local script = GetLuaBehaviour(go, "Game.UI.Common.CommonTipsBoardBuff")
            if not KTool.IsNull(script) then
                -- 刷新提示板内容
                script.Env:RefreshBoardByContent(self.skillName, self.skillDesc)
                -- 修正一次坐标位置
                script.Env:FixBoardPosition(self.controller.gameObject)
                -- 界面关闭时的回调
                script.Env:SetCloseCallBack(function()
                    self.tipsBoard = nil
                    if not isNull(self.Img_Selected) then
                        KTool.SetActive(self.Img_Selected.gameObject, false)
                    end
                end)
                -- 设置图标
                local rawImg = script.Env:SetSkillMode()
                if rawImg then
                    local skillVo = UIBattlingTools.GetSkillCardInfoByTwoParam(self.skillId, 1)
                    local isAoe = checkBool(checkNumber(skillVo.isAoe) > 0)
                    local skillType = skillVo.skillType
                    if skillType < 3 then
                        local label = skillVo.showLabel -- 技能 Icon
                        local showLabel = UICommonUtils:GetSkillShowLabelWithStar(label, 1)
                        local condition = showLabel >= 1 and showLabel <= 6 and isAoe
                        local skillIconPath = condition and UIBattlingTools.GetEnemySkillTypeAOEIconPath_1(showLabel) or
                        UIBattlingTools.GetEnemySkillTypeIconPath_1(showLabel)
                        UIBattlingCtrlMgr:GetInstance():SetImgByDynamicAtlas(rawImg, skillIconPath)
                    else
                        UIBattlingCtrlMgr:GetInstance():SetImgByDynamicAtlas(rawImg, "UIBattlingDynamicAtlas/battle_icon_sp.png")
                    end
                    rawImg:SetNativeSize()
                end
            end
        end
    end, true, UIModule.RootCanvas.transform)
    KTool.SetActive(self.Img_Selected.gameObject, true)
end

function BattlingEnemySkillDesc:SetSelectedState(boolean)
    KTool.SetActive(self.Img_Selected.gameObject, boolean)
end

return BattlingEnemySkillDesc
